"""Derive the graded truth and check it against the lock.  Standard library only.

Run as:  python3 -I -S /tests/derive_truth.py
Prints one JSON document on stdout and exits 0, or exits 2 on any failure
(the grader maps that to an infrastructure error, never to a model failure).

The lock (tests/lock.json) is a SHA-256 over, together:
  * the regenerated bytes of every file shipped to the agent under /app/data,
  * the hidden material constants,
  * the true temperatures for the visible scenarios,
  * the held-out scenarios (never shipped) and their true temperatures.
A tampered generator therefore has to reproduce the shipped bytes *and* the
graded answers exactly, i.e. be the real generator.
"""

import hashlib
import json
import os
import sys

# -I implies -P, so the script directory is not on sys.path.  /tests is the
# verifier's own read-only overlay (not an agent-writable path), so adding it
# only exposes the sibling modules instance.py and thermal_model.py.
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import instance  # noqa: E402


def canonical_digest(files, visible, heldout):
    h = hashlib.sha256()
    for name in sorted(files):
        h.update(("=== %s %d\n" % (name, len(files[name]))).encode("ascii"))
        h.update(files[name])
    h.update(b"\n--- hidden constants ---\n")
    h.update(("%r %r %r\n" % (instance.K_SPECIMEN, instance.RHO_C_SPECIMEN, instance.R_LEADS)).encode("ascii"))
    h.update(b"\n--- graded answers ---\n")
    for sid, temp in visible:
        h.update(("%s %.6f\n" % (sid, temp)).encode("ascii"))
    for sc, temp in heldout:
        h.update((json.dumps(sc, sort_keys=True) + " %.6f\n" % temp).encode("ascii"))
    h.update(("tol %r %r\n" % (instance.REL_TOL, instance.ABS_TOL)).encode("ascii"))
    return h.hexdigest()


def strip_id(sc):
    return json.dumps({k: v for k, v in sc.items() if k != "id"}, sort_keys=True)


def main():
    files, visible, heldout = instance.build()
    if not heldout:
        raise RuntimeError("held-out set is empty")
    ids = [sc["id"] for sc, _ in heldout] + [sid for sid, _ in visible]
    if len(set(ids)) != len(ids):
        raise RuntimeError("duplicate scenario ids")
    shipped = {strip_id(sc) for sc in instance.VISIBLE}
    if any(strip_id(sc) in shipped for sc, _ in heldout):
        raise RuntimeError("a held-out scenario duplicates a visible one")
    digest = canonical_digest(files, visible, heldout)
    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "lock.json")) as fh:
        locked = json.load(fh)["sha256"]
    if digest != locked:
        raise RuntimeError("truth digest %s does not match lock %s" % (digest, locked))
    doc = {
        "digest": digest,
        "rel_tol": instance.REL_TOL,
        "abs_tol": instance.ABS_TOL,
        "visible_ids": [sid for sid, _ in visible],
        "visible": {sid: temp for sid, temp in visible},
        "visible_scenarios": instance.VISIBLE,
        "heldout": [{"scenario": sc, "T_true": temp} for sc, temp in heldout],
    }
    sys.stdout.write(json.dumps(doc))
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # any failure here is an infrastructure error
        sys.stderr.write("derive_truth failed: %r\n" % (exc,))
        sys.exit(2)
